#define DELIVERY      ds[0x4b]
#define ROW           ds[0xe2f4]
#define ROW_PERSON(r) word_at(ds, (uint16_t)(0xea2a + (r) * 2))
#define SHOWN         word_at(ds, 0x4600)
#define SET_SHOWN(p) \
  (ds[0x4600] = (uint8_t)(p), ds[0x4601] = (uint8_t)((p) >> 8))
#define ADD_BYTE(n, l, p) opeu_add_byte(n, l, p)
